  "congrats.milestone.capital": { en: "Province Center!", th: "จังหวัด!" },
  "congrats.milestone.metropolis": { en: "Metropolis!", th: "นคร!" },
  "congrats.milestone.megalopolis": { en: "Megalopolis!", th: "มหานคร!" },
  "congrats.promoted": { en: "You rise to the rank of {rank}.", th: "คุณได้เลื่อนยศเป็น{rank}" },
  "congrats.btn.ok": { en: "Celebrate!", th: "ร่วมยินดี!" },
  "msg.welcome": { en: "Welcome to PhaiCity", th: "ยินดีต้อนรับสู่ PhaiCity" },
  "msg.need.fire_station": { en: "Citizens demand a Fire Station", th: "ชาวเมืองเรียกร้องให้สร้างสถานีดับเพลิง" },
  "msg.need.police_station": { en: "Citizens demand a Police Station", th: "ชาวเมืองเรียกร้องให้ตั้งสถานีตำรวจ" },
  "msg.need.stadium": { en: "Residents demand a Sports Stadium", th: "ประชาชนเรียกร้องให้สร้างสนามกีฬา" },
  "msg.need.electricity": { en: "City needs more power: build a Power Plant", th: "ไฟฟ้าไม่พอ โปรดสร้างโรงไฟฟ้าเพิ่ม" },
  "msg.need.airport": { en: "Commerce requires an Airport for trade", th: "ย่านการค้าต้องการสนามบินเพื่อขยายการขนส่ง" },
  "msg.need.seaport": { en: "Industry requires a Seaport for exports", th: "โรงงานอุตสาหกรรมต้องการท่าเรือพาณิชย์" },
  "msg.need.more_res": { en: "More residential zones needed", th: "เมืองต้องการเขตที่อยู่อาศัยเพิ่มขึ้น" },
  "msg.need.more_com": { en: "More commercial zones needed", th: "เมืองต้องการเขตพาณิชย์เพิ่มขึ้น" },
  "msg.need.more_ind": { en: "More industrial zones needed", th: "เมืองต้องการเขตอุตสาหกรรมเพิ่มขึ้น" },
  "msg.need.more_roads": { en: "More roads required to connect zones", th: "ต้องการถนนเพิ่มเติมเพื่อเชื่อมต่อเมือง" },
  "msg.need.more_rails": { en: "Rail transit system needed to relieve traffic", th: "ระบบทางรถไฟยังไม่เพียงพอต่อการสัญจร" },
  "msg.fund.fire": { en: "Fire stations need budget funding", th: "สถานีดับเพลิงขาดแคลนงบซ่อมบำรุง" },
  "msg.fund.police": { en: "Police stations need budget funding", th: "สถานีตำรวจขาดแคลนงบซ่อมบำรุง" },
  "msg.fund.road": { en: "Roads deteriorating due to lack of funding", th: "ถนนเริ่มพังชำรุดทรุดโทรมเนื่องจากขาดงบซ่อมบำรุง" },
  "msg.bad.blackouts": { en: "Brownouts reported: build another Power Plant", th: "เกิดไฟตกเป็นวงกว้าง โปรดสร้างโรงไฟฟ้าเพิ่ม" },
  "msg.bad.not_enough_power": { en: "Blackouts reported: insufficient power capacity", th: "เกิดไฟฟ้าดับทั่วเมือง! กำลังผลิตไฟฟ้าไม่เพียงพอ" },
  "msg.bad.earthquake": { en: "Major earthquake reported !!", th: "เกิดแผ่นดินไหวรุนแรงขึ้นในพื้นที่ !!" },
  "msg.bad.explosion": { en: "Major explosion detected!", th: "เกิดเหตุระเบิดรุนแรงขึ้นในเมือง!" },
  "msg.bad.flooding": { en: "Flooding reported across city!", th: "รายงานด่วน: น้ำท่วมหลากเข้าท่วมพื้นที่เมือง!" },
  "msg.bad.fire": { en: "Fire outbreak reported!", th: "รายงานเหตุด่วน: เกิดเพลิงไหม้ลุกลาม!" },
  "msg.bad.heavy_traffic": { en: "Heavy traffic congestion reported", th: "สภาพการจราจรติดขัดสะสมหนาแน่น" },
  "msg.bad.traffic_jams": { en: "Frequent traffic jams annoying citizens", th: "ประชาชนร้องเรียน: การจราจรติดขัดเรื้อรัง" },
  "msg.bad.helicopter_crash": { en: "A helicopter has crashed!", th: "เกิดเหตุเฮลิคอปเตอร์ตกกระแทกพื้น!" },
  "msg.bad.plane_crash": { en: "An airplane has crashed!", th: "เกิดอุบัติเหตุเครื่องบินตกในเขตเมือง!" },
  "msg.bad.train_crash": { en: "A train collision reported!", th: "เกิดอุบัติเหตุขบวนรถไฟชนกัน/ตกราง!" },
  "msg.bad.ship_crash": { en: "Shipwreck reported in waters!", th: "รายงานอุบัติเหตุเรือชนกันหรือเรืออับปาง!" },
  "msg.bad.high_crime": { en: "Crime rate is dangerously high!", th: "สถิติอาชญากรรมพุ่งสูงขึ้นขั้นวิกฤต!" },
  "msg.bad.high_pollution": { en: "Air & water pollution dangerously high!", th: "มลพิษทางอากาศและสิ่งแวดล้อมเกินค่ามาตรฐาน!" },
  "msg.bad.monster": { en: "A Giant Naga has emerged !", th: "พญานาคยักษ์ปรากฏกายขึ้นแล้ว !" },
  "msg.bad.tornado": { en: "Severe tornado spotted!", th: "พายุงวงช้างพัดถล่มบ้านเรือนเสียหาย!" },
  "msg.bad.meltdown": { en: "Nuclear reactor meltdown occurred !!", th: "เตาปฏิกรณ์นิวเคลียร์หลอมละลาย เกิดการรั่วไหล !!" },
  "msg.bad.tax_too_high": { en: "Citizens upset: local taxes are too high!", th: "ประชาชนไม่พอใจอย่างยิ่ง: อัตราภาษีท้องถิ่นแพงเกินไป!" },
  "msg.bad.no_money": { en: "YOUR CITY HAS GONE BANKRUPT!", th: "คลังเมืองล้มละลายแล้ว! เงินหมดเกลี้ยง!" },
  "msg.good.reach_town": { en: "Population reached 2,000 (Town level)", th: "ประชากรในเมืองทะลุ 2,000 คนแล้ว (ยกฐานะเป็นตำบล)" },
  "msg.good.reach_city": { en: "Population reached 10,000 (City level)", th: "ประชากรในเมืองทะลุ 10,000 คนแล้ว (ยกฐานะเป็นอำเภอ)" },
  "msg.good.reach_capital": { en: "Population reached 50,000 (Province level)", th: "ประชากรในเมืองทะลุ 50,000 คนแล้ว (ยกฐานะเป็นจังหวัด)" },
  "msg.good.reach_metro": { en: "Population reached 100,000 (Metropolis level)", th: "ประชากรในเมืองทะลุ 100,000 คนแล้ว (ยกฐานะเป็นนคร)" },
  "msg.good.reach_megalopolis": { en: "Population reached 500,000 (Megalopolis level)", th: "ประชากรในเมืองทะลุ 500,000 คนแล้ว (ยกฐานะเป็นมหานคร)" },
